/** SYNCHRONOUS claim, taken BEFORE an awaited call. The caller MUST release it on every path
 *  (success AND failure), otherwise the leaked claim permanently shrinks the effective cap. */
claim(): boolean {
  if (!this.roomLeft()) return false;
  this.pending += 1;
  return true;
}

/** Use this instead of a bare claim()/settle() pair so a rejected call cannot leak its claim. */
async withClaim<T>(cost: (result: T) => { usd: number; cached: boolean }, fn: () => Promise<T>): Promise<T | undefined> {
  if (!this.claim()) return undefined;
  try {
    const result = await fn();
    const { usd, cached } = cost(result);
    this.settle(usd, cached);
    return result;
  } catch (err) {
    this.settle(0, true);   // release the reservation; nothing was spent
    throw err;
  }
}

