export function safeName(name: string): string {
  const cleaned = name.replace(/[^A-Za-z0-9._-]/g, "_").replace(/\.\.+/g, "_").slice(0, 64);
  // COLLISION-PROOF: distinct names can sanitise to the same string (`a/b` vs `a_b`), and two
  // names sharing the first 64 chars truncate to the same value — either would silently merge
  // two indexes into one file (same class as D-027 in src/targets.ts).
  if (cleaned !== name) return `${cleaned.slice(0, 48)}-${createHash("sha256").update(name).digest("hex").slice(0, 8)}`;

export function saveTargets(list: Target[]): void {
  const p = targetsPath();
  mkdirSync(dirname(p), { recursive: true });
  // ATOMIC: write a sibling temp file and rename it into place, so a crash/ENOSPC can never
  // leave a truncated registry (which would make loadTargets throw JM_TARGETS_CORRUPT forever).
  const tmp = `${p}.${process.pid}.tmp`;
  writeFileSync(tmp, JSON.stringify(list, null, 2) + "\n");
  renameSync(tmp, p);
}

